func _physics_process(delta: float) -> void :
				if _hit_reaction_cooldown > 0.0:
								_hit_reaction_cooldown = max(0.0, _hit_reaction_cooldown - delta)
				if _hit_reaction_remaining > 0.0:
								_hit_reaction_remaining = max(0.0, _hit_reaction_remaining - delta)
								if _hit_reaction_remaining <= 0.0:
												$SpriteContainer / Sprite.self_modulate = Color.white

				last_check_time += delta * (0.5 + 0.5 * randf())
